import UIKit
import SwiftUI
import ComposeApp

struct ComposeView: UIViewControllerRepresentable {
    func makeUIViewController(context: Context) -> UIViewController {
        // MainViewControllerKt is generated by Kotlin/Native from the
        // `MainViewController()` function in composeApp/iosMain. The bridge gives
        // the shared Kotlin UI access to HaishinKit for contributor live streams.
        MainViewControllerKt.MainViewController(liveStreamBridge: HaishinKitLiveStreamBridge())
    }

    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {}
}

struct ContentView: View {
    var body: some View {
        ComposeView()
            .ignoresSafeArea(.keyboard) // Let Compose handle the keyboard.
    }
}
